/*
 * bpf_loader.c - eBPF program loader and ring buffer interface
 *
 * Opens, loads, and attaches all three owlbear BPF skeletons.
 * Graceful degradation: each skeleton is independent. If LSM hooks
 * fail (missing CONFIG_BPF_LSM), kprobe detection still works.
 */

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <bpf/libbpf.h>
#include <bpf/bpf.h>

#include "bpf_loader.h"
#include "log.h"

/* Skeleton headers generated by bpftool */
#include "owlbear_lsm.skel.h"
#include "owlbear_trace.skel.h"
#include "owlbear_kprobe.skel.h"
#include "owlbear_net.skel.h"

/*
 * BPF event structure — must match owlbear_common.bpf.h.
 * Duplicated here because the BPF header uses vmlinux.h types.
 */
struct owl_bpf_event {
	uint64_t timestamp_ns;
	uint32_t event_type;
	uint32_t severity;
	uint32_t pid;
	uint32_t target_pid;
	char     comm[16];
	char     detail[48];
};

struct owl_bpf_ctx {
	struct owlbear_lsm_bpf    *lsm;
	struct owlbear_trace_bpf  *trace;
	struct owlbear_kprobe_bpf *kprobe;
	struct owlbear_net_bpf    *net;
	struct ring_buffer        *ringbuf;

	bool has_lsm;
	bool has_trace;
	bool has_kprobe;
	bool has_net;

	/* Map fds for populating from userspace */
	int protected_pids_fd;
	int allowed_pids_fd;

	/* User callback */
	owl_bpf_event_cb event_cb;
	void            *event_cb_ctx;
};

/* -------------------------------------------------------------------------
 * Pure conversion function (testable without BPF)
 * ----------------------------------------------------------------------- */

int owl_bpf_event_convert(const void *bpf_data, size_t bpf_size,
			   struct owlbear_event *out)
{
	if (!bpf_data || !out)
		return -1;

	if (bpf_size < sizeof(struct owl_bpf_event))
		return -1;

	const struct owl_bpf_event *bev = bpf_data;

	memset(out, 0, sizeof(*out));
	out->timestamp_ns = bev->timestamp_ns;
	out->event_type = bev->event_type;
	out->severity = bev->severity;
	out->source = OWL_SRC_EBPF;
	out->pid = bev->pid;
	out->target_pid = bev->target_pid;
	memcpy(out->comm, bev->comm, sizeof(out->comm));

	/*
	 * Map the detail string into the appropriate payload union
	 * based on event type.
	 */
	switch (bev->event_type) {
	case OWL_EVENT_PTRACE_ATTEMPT:
	case OWL_EVENT_PROC_MEM_ACCESS:
	case OWL_EVENT_VM_READV_ATTEMPT:
	case OWL_EVENT_VM_WRITEV_ATTEMPT:
	case OWL_EVENT_MPROTECT_EXEC:
		out->payload.memory.caller_pid = bev->pid;
		memcpy(out->payload.memory.caller_comm, bev->comm,
		       sizeof(out->payload.memory.caller_comm) < sizeof(bev->comm)
		       ? sizeof(out->payload.memory.caller_comm)
		       : sizeof(bev->comm));
		break;

	case OWL_EVENT_MODULE_LOAD:
		memcpy(out->payload.module.name, bev->detail,
		       sizeof(out->payload.module.name) < sizeof(bev->detail)
		       ? sizeof(out->payload.module.name)
		       : sizeof(bev->detail));
		break;

	case OWL_EVENT_NET_CONNECT:
	case OWL_EVENT_NET_SEND:
		memcpy(&out->payload.network.dst_addr, bev->detail + 0, 4);
		memcpy(&out->payload.network.dst_port, bev->detail + 4, 2);
		memcpy(&out->payload.network.protocol, bev->detail + 6, 2);
		memcpy(&out->payload.network.bytes,    bev->detail + 8, 8);
		memcpy(out->payload.network.comm, bev->comm,
		       sizeof(out->payload.network.comm) < sizeof(bev->comm)
		       ? sizeof(out->payload.network.comm)
		       : sizeof(bev->comm));
		break;

	default:
		/* Copy detail into raw payload as fallback */
		memcpy(out->payload.raw, bev->detail,
		       sizeof(out->payload.raw) < sizeof(bev->detail)
		       ? sizeof(out->payload.raw)
		       : sizeof(bev->detail));
		break;
	}

	return 0;
}

/* -------------------------------------------------------------------------
 * Ring buffer callback — invoked by libbpf for each event
 * ----------------------------------------------------------------------- */

static int ringbuf_event_handler(void *ctx, void *data, size_t data_sz)
{
	struct owl_bpf_ctx *bctx = ctx;
	struct owlbear_event ev;

	if (owl_bpf_event_convert(data, data_sz, &ev) < 0)
		return 0;  /* Skip malformed events */

	if (bctx->event_cb)
		bctx->event_cb(&ev, bctx->event_cb_ctx);

	return 0;
}

/* -------------------------------------------------------------------------
 * Libbpf log callback — suppress noisy output unless debug
 * ----------------------------------------------------------------------- */

static int libbpf_print_fn(enum libbpf_print_level level,
			    const char *format, va_list args)
{
	if (level == LIBBPF_DEBUG && g_owl_log_level < OWL_LOG_DBG)
		return 0;
	return vfprintf(stderr, format, args);
}

/* -------------------------------------------------------------------------
 * Map fd extraction — find the protected_pids fd from whichever
 * skeleton loaded first (legacy single-map accessors only).
 * ----------------------------------------------------------------------- */

static int find_map_fd(struct owl_bpf_ctx *ctx, const char *name)
{
	int fd = -1;

	if (ctx->lsm) {
		struct bpf_map *map = bpf_object__find_map_by_name(
			ctx->lsm->obj, name);
		if (map)
			fd = bpf_map__fd(map);
	}

	if (fd < 0 && ctx->trace) {
		struct bpf_map *map = bpf_object__find_map_by_name(
			ctx->trace->obj, name);
		if (map)
			fd = bpf_map__fd(map);
	}

	if (fd < 0 && ctx->kprobe) {
		struct bpf_map *map = bpf_object__find_map_by_name(
			ctx->kprobe->obj, name);
		if (map)
			fd = bpf_map__fd(map);
	}

	if (fd < 0 && ctx->net) {
		struct bpf_map *map = bpf_object__find_map_by_name(
			ctx->net->obj, name);
		if (map)
			fd = bpf_map__fd(map);
	}

	return fd;
}

/* -------------------------------------------------------------------------
 * Public API
 * ----------------------------------------------------------------------- */

struct owl_bpf_ctx *owl_bpf_init(owl_bpf_event_cb cb, void *cb_ctx)
{
	return owl_bpf_init_selected(cb, cb_ctx, OWL_BPF_ALL, true);
}

struct owl_bpf_ctx *owl_bpf_init_selected(owl_bpf_event_cb cb, void *cb_ctx,
                                        unsigned sensors, bool enforce)
{
	struct owl_bpf_ctx *ctx;
	int err;

	ctx = calloc(1, sizeof(*ctx));
	if (!ctx)
		return NULL;

	ctx->event_cb = cb;
	ctx->event_cb_ctx = cb_ctx;
	ctx->protected_pids_fd = -1;
	ctx->allowed_pids_fd = -1;

	libbpf_set_print(libbpf_print_fn);

	/* --- LSM skeleton --- */
	ctx->lsm = (sensors & 1u) ? owlbear_lsm_bpf__open() : NULL;
	if (ctx->lsm) {
		ctx->lsm->rodata->enforce_mode = enforce;
		if (owlbear_lsm_bpf__load(ctx->lsm)) {
			owlbear_lsm_bpf__destroy(ctx->lsm);
			ctx->lsm = NULL;
		}
	}
	if (!ctx->lsm) {
		if (sensors & 1u)
			OWL_WARN("BPF LSM load failed: %s", strerror(errno));
	} else {
		err = owlbear_lsm_bpf__attach(ctx->lsm);
		if (err) {
			OWL_WARN("BPF LSM attach failed: %s", strerror(-err));
			owlbear_lsm_bpf__destroy(ctx->lsm);
			ctx->lsm = NULL;
		} else {
			ctx->has_lsm = true;
			OWL_INFO("BPF LSM programs attached");
		}
	}

	/* --- Tracepoint skeleton --- */
	ctx->trace = (sensors & 2u) ? owlbear_trace_bpf__open_and_load() : NULL;
	if (!ctx->trace) {
		if (sensors & 2u)
			OWL_WARN("BPF trace load failed: %s", strerror(errno));
	} else {
		err = owlbear_trace_bpf__attach(ctx->trace);
		if (err) {
			OWL_WARN("BPF trace attach failed: %s", strerror(-err));
			owlbear_trace_bpf__destroy(ctx->trace);
			ctx->trace = NULL;
		} else {
			ctx->has_trace = true;
			OWL_INFO("BPF tracepoint programs attached");
		}
	}

	/* --- Kprobe skeleton --- */
	ctx->kprobe = (sensors & 4u) ? owlbear_kprobe_bpf__open_and_load() : NULL;
	if (!ctx->kprobe) {
		if (sensors & 4u)
			OWL_WARN("BPF kprobe load failed: %s", strerror(errno));
	} else {
		err = owlbear_kprobe_bpf__attach(ctx->kprobe);
		if (err) {
			OWL_WARN("BPF kprobe attach failed: %s", strerror(-err));
			owlbear_kprobe_bpf__destroy(ctx->kprobe);
			ctx->kprobe = NULL;
		} else {
			ctx->has_kprobe = true;
			OWL_INFO("BPF kprobe programs attached");
		}
	}

	/* --- Net kprobe skeleton --- */
	ctx->net = (sensors & 8u) ? owlbear_net_bpf__open_and_load() : NULL;
	if (!ctx->net) {
		if (sensors & 8u)
			OWL_WARN("BPF net load failed: %s", strerror(errno));
	} else {
		err = owlbear_net_bpf__attach(ctx->net);
		if (err) {
			OWL_WARN("BPF net attach failed: %s", strerror(-err));
			owlbear_net_bpf__destroy(ctx->net);
			ctx->net = NULL;
		} else {
			ctx->has_net = true;
			OWL_INFO("BPF net kprobe programs attached");
		}
	}

	/* If nothing loaded, still return ctx (degraded mode) */
	if (!ctx->has_lsm && !ctx->has_trace && !ctx->has_kprobe &&
	    !ctx->has_net) {
		OWL_WARN("no BPF programs loaded, running in kmod-only mode");
	}

	/* Extract map fds */
	ctx->protected_pids_fd = find_map_fd(ctx, "protected_pids");
	ctx->allowed_pids_fd = find_map_fd(ctx, "allowed_pids");

	/* Objects own distinct rings: consume every attached source. */
	struct bpf_object *objects[] = {
		ctx->lsm ? ctx->lsm->obj : NULL,
		ctx->trace ? ctx->trace->obj : NULL,
		ctx->kprobe ? ctx->kprobe->obj : NULL,
		ctx->net ? ctx->net->obj : NULL,
	};
	for (unsigned i = 0; i < 4; i++) {
		if (!objects[i]) continue;
		int fd = bpf_object__find_map_fd_by_name(objects[i], "events");
		if (fd < 0) { owl_bpf_destroy(ctx); return NULL; }
		if (!ctx->ringbuf)
			ctx->ringbuf = ring_buffer__new(fd, ringbuf_event_handler, ctx, NULL);
		else if (ring_buffer__add(ctx->ringbuf, fd, ringbuf_event_handler, ctx)) {
			owl_bpf_destroy(ctx);
			return NULL;
		}
		if (!ctx->ringbuf) {
			owl_bpf_destroy(ctx);
			return NULL;
		}
	}

	return ctx;
}

void owl_bpf_destroy(struct owl_bpf_ctx *ctx)
{
	if (!ctx)
		return;

	if (ctx->ringbuf)
		ring_buffer__free(ctx->ringbuf);

	if (ctx->lsm)
		owlbear_lsm_bpf__destroy(ctx->lsm);
	if (ctx->trace)
		owlbear_trace_bpf__destroy(ctx->trace);
	if (ctx->kprobe)
		owlbear_kprobe_bpf__destroy(ctx->kprobe);
	if (ctx->net)
		owlbear_net_bpf__destroy(ctx->net);

	free(ctx);
}

int owl_bpf_protect_pid(struct owl_bpf_ctx *ctx, uint32_t pid)
{
	if (!ctx || ctx->protected_pids_fd < 0)
		return -1;

	uint32_t flags = 0;
	return bpf_map_update_elem(ctx->protected_pids_fd, &pid, &flags, BPF_ANY);
}

int owl_bpf_allow_pid(struct owl_bpf_ctx *ctx, uint32_t pid)
{
	if (!ctx || ctx->allowed_pids_fd < 0)
		return -1;

	uint32_t level = 1;
	return bpf_map_update_elem(ctx->allowed_pids_fd, &pid, &level, BPF_ANY);
}

int owl_bpf_ringbuf_fd(const struct owl_bpf_ctx *ctx)
{
	if (!ctx || !ctx->ringbuf)
		return -1;

	return ring_buffer__epoll_fd(ctx->ringbuf);
}

int owl_bpf_poll(struct owl_bpf_ctx *ctx, int timeout_ms)
{
	if (!ctx || !ctx->ringbuf)
		return 0;

	return ring_buffer__poll(ctx->ringbuf, timeout_ms);
}

bool owl_bpf_has_lsm(const struct owl_bpf_ctx *ctx)
{
	return ctx && ctx->has_lsm;
}

bool owl_bpf_has_trace(const struct owl_bpf_ctx *ctx)
{
	return ctx && ctx->has_trace;
}

bool owl_bpf_has_kprobe(const struct owl_bpf_ctx *ctx)
{
	return ctx && ctx->has_kprobe;
}

bool owl_bpf_has_net(const struct owl_bpf_ctx *ctx)
{
	return ctx && ctx->has_net;
}

unsigned owl_bpf_attached(const struct owl_bpf_ctx *ctx)
{
	return owl_bpf_has_lsm(ctx) | (owl_bpf_has_trace(ctx) << 1) |
	       (owl_bpf_has_kprobe(ctx) << 2) | (owl_bpf_has_net(ctx) << 3);
}

int owl_bpf_configure(struct owl_bpf_ctx *ctx, uint32_t target, uint32_t daemon_pid)
{
	if (!ctx) return -1;
	struct bpf_object *objects[] = {
		ctx->lsm ? ctx->lsm->obj : NULL, ctx->trace ? ctx->trace->obj : NULL,
		ctx->kprobe ? ctx->kprobe->obj : NULL, ctx->net ? ctx->net->obj : NULL,
	};
	uint32_t value = 1;
	for (unsigned i = 0; i < 4; i++) {
		if (!objects[i]) continue;
		int protected_fd = bpf_object__find_map_fd_by_name(objects[i], "protected_pids");
		int allowed_fd = bpf_object__find_map_fd_by_name(objects[i], "allowed_pids");
		if (protected_fd < 0 || allowed_fd < 0 ||
		    bpf_map_update_elem(allowed_fd, &daemon_pid, &value, BPF_ANY) ||
		    bpf_map_update_elem(allowed_fd, &target, &value, BPF_ANY) ||
		    bpf_map_update_elem(protected_fd, &target, &value, BPF_ANY))
			return -1;
	}
	return 0;
}
